import{_ as a,o as s,c as n,a6 as o}from"./chunks/framework.DNkVJs23.js";const h=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/es-419/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/es-419/faq/"}],["meta",{"property":"og:title","content":"Preguntas frecuentes | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Datos de Monster Hunter y búsqueda de armaduras para Wilds, Rise con Sunbreak y World con Iceborne."}]]},"headers":[],"relativePath":"es-419/faq/index.md","filePath":"es-419/faq/index.md"}'),i={name:"es-419/faq/index.md"};function r(t,e,d,l,p,u){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><h2 id="¿que-juegos-son-compatibles" tabindex="-1">¿Qué juegos son compatibles? <a class="header-anchor" href="#¿que-juegos-son-compatibles" aria-label="Permalink to &quot;¿Qué juegos son compatibles?&quot;">​</a></h2><p>Wilds, Rise con Sunbreak y World con Iceborne. Los datos y las mecánicas se mantienen separados por juego; puedes cambiar de juego desde el inicio.</p><h2 id="¿donde-puedo-descargar-la-app" tabindex="-1">¿Dónde puedo descargar la app? <a class="header-anchor" href="#¿donde-puedo-descargar-la-app" aria-label="Permalink to &quot;¿Dónde puedo descargar la app?&quot;">​</a></h2><p>Android está disponible en <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> y HarmonyOS en <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. La versión para iOS está en preparación. Consulta las <a href="./../#download">descargas</a>; la disponibilidad depende de la región y del dispositivo.</p><h2 id="¿funciona-sin-conexion" tabindex="-1">¿Funciona sin conexión? <a class="header-anchor" href="#¿funciona-sin-conexion" aria-label="Permalink to &quot;¿Funciona sin conexión?&quot;">​</a></h2><p>Los datos están incluidos en la app. La consulta, las búsquedas, los favoritos y la búsqueda de armaduras funcionan localmente. Los enlaces externos y las actualizaciones requieren conexión.</p><h2 id="¿como-funciona-la-busqueda-de-sets" tabindex="-1">¿Cómo funciona la búsqueda de sets? <a class="header-anchor" href="#¿como-funciona-la-busqueda-de-sets" aria-label="Permalink to &quot;¿Cómo funciona la búsqueda de sets?&quot;">​</a></h2><p>Define habilidades y niveles, fija o excluye equipo y limita las decoraciones a las que tienes. Rise también admite tus talismanes y armaduras aumentadas. Los resultados dependen de los datos y los criterios; no es una calculadora de daño.</p><h2 id="¿que-idiomas-estan-disponibles" tabindex="-1">¿Qué idiomas están disponibles? <a class="header-anchor" href="#¿que-idiomas-estan-disponibles" aria-label="Permalink to &quot;¿Qué idiomas están disponibles?&quot;">​</a></h2><p>La app ofrece 14 idiomas. Algunos textos del juego pueden aparecer en inglés. Si falta un texto en español latinoamericano, se busca primero en español de España y después en inglés.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="¿es-una-app-oficial" tabindex="-1">¿Es una app oficial? <a class="header-anchor" href="#¿es-una-app-oficial" aria-label="Permalink to &quot;¿Es una app oficial?&quot;">​</a></h2><p>No. Es una app independiente de aficionados, sin afiliación ni aprobación de CAPCOM. Las imágenes y los datos de Monster Hunter pertenecen a CAPCOM Co., Ltd.</p>',14)])])}const f=a(i,[["render",r]]);export{h as __pageData,f as default};
